const commands = [
  {id:'goto',icon:'⌖',group:'ДВИЖЕНИЕ',number:'01 — NAVIGATION',title:'Перейти к цели',desc:'Укажите координаты или ID блока — Baritone построит оптимальный маршрут.',builder:'Куда отправиться',hint:'Форматы: Y — высота; X Z — горизонтальная плоскость; X Y Z — полные координаты в трёх измерениях. Также можно указать ID блока. Относительные координаты начинаются с ~.',fields:[['target','Координаты: X Z или X Y Z; высота: Y; либо ID блока','100 64 200','full']],validate:v=>v.target?'':'Укажите координаты или ID блока.',build:v=>`goto ${v.target||''}`},
  {id:'follow',icon:'◎',group:'ДВИЖЕНИЕ',number:'05 — FOLLOW',title:'Следование',desc:'Следуйте за всеми игроками, сущностями либо за конкретными целями.',builder:'Цель следования',hint:'Для конкретных целей укажите имена игроков или ID сущностей через пробел.',fields:[['mode','Режим','','full','select',[['players','Все игроки'],['entities','Все сущности'],['player','Конкретные игроки'],['entity','Типы сущностей']]],['targets','Цели (для конкретного режима)','Steve или zombie cow','full']],validate:v=>['player','entity'].includes(v.mode)&&!v.targets?'Укажите хотя бы одну конкретную цель.':'',build:v=>`follow ${v.mode||'players'} ${['player','entity'].includes(v.mode)?v.targets||'':''}`},
  {id:'mine',icon:'◆',group:'ЗАДАЧИ',number:'',title:'Добыча ресурсов',desc:'Задайте отдельное количество для каждого блока — отсчёт начнётся с момента запуска.',builder:'Параметры добычи',hint:'Количество задаётся отдельно перед иконкой каждого блока. Если количество не указано, добыча будет продолжаться бесконечно.',blockPicker:true,fields:[],validate:(v,s)=>{if(!s.size)return'Выберите хотя бы один блок.';if([...s].some(id=>CATALOG_BY_ID.get(id)?.kind==='item'))return'Команда Mine принимает только размещаемые блоки, а не обычные предметы.';const values=[...s].map(id=>state.blockQuantities[id]||'');if(values.some(Boolean)&&values.some(value=>!value))return'Укажите количество для каждого блока либо очистите все поля.';return values.some(value=>value&&!/^[1-9]\d*$/.test(value))?'Количество должно быть целым числом больше нуля.':''},build:(v,s)=>{const ids=[...s];const quota=ids.some(id=>state.blockQuantities[id]);return quota?`minequota ${ids.map(id=>`${id}=${state.blockQuantities[id]}`).join(' ')}`:`mine ${ids.join(' ')}`}},
  {id:'explore',icon:'✣',group:'ЗАДАЧИ',number:'03 — DISCOVERY',title:'Исследование мира',desc:'Автоматически исследуйте новые чанки вокруг выбранной области.',builder:'Область исследования',hint:'Оставьте обе координаты пустыми для старта от текущей позиции.',fields:[['x','Центр X (необязательно)','0'],['z','Центр Z (необязательно)','0']],validate:v=>Boolean(v.x)!==Boolean(v.z)?'Укажите одновременно X и Z либо оставьте оба поля пустыми.':'',build:v=>`explore ${v.x&&v.z?`${v.x} ${v.z}`:''}`},
  {id:'farm',icon:'♧',group:'ЗАДАЧИ',number:'04 — FARMING',title:'Автоферма',desc:'Собирайте и пересаживайте готовые культуры в заданном радиусе.',builder:'Параметры фермы',hint:'Waypoint можно указать только вместе с радиусом.',fields:[['radius','Радиус (необязательно)','32'],['waypoint','Waypoint (необязательно)','home']],validate:v=>v.waypoint&&!v.radius?'Для waypoint укажите радиус.':v.radius&&!/^\d+$/.test(v.radius)?'Радиус должен быть целым положительным числом.':'',build:v=>`farm ${[v.radius,v.waypoint].filter(Boolean).join(' ')}`},
  {id:'build',icon:'▧',group:'ЗАДАЧИ',number:'06 — BUILD',title:'Строительство',desc:'Постройте схему из папки schematics игрового клиента.',builder:'Файл схемы',hint:'После имени файла можно указать ровно три координаты точки начала.',fields:[['file','Имя схемы','castle.schematic','full'],['origin','Начальные X Y Z (необязательно)','100 64 100','full']],validate:v=>!v.file?'Укажите имя файла схемы.':v.origin&&v.origin.trim().split(/\s+/).length!==3?'Начальная позиция должна содержать X Y Z.':'',build:v=>`build ${[v.file,v.origin].filter(Boolean).join(' ')}`},
  {id:'find',icon:'⌕',group:'ИНСТРУМЕНТЫ',number:'',title:'Поиск блоков',desc:'Найдите координаты выбранных блоков в кэше уже исследованного мира.',builder:'Что найти',hint:'Find выводит известные координаты в игровой чат и не запускает движение.',blockPicker:true,fields:[],validate:(v,s)=>!s.size?'Выберите хотя бы один блок.':[...s].some(id=>CATALOG_BY_ID.get(id)?.kind==='item')?'Команда Find принимает только размещаемые блоки, а не обычные предметы.':'',build:(v,s)=>`find ${[...s].join(' ')}`},
  {id:'surface',icon:'⇡',group:'ИНСТРУМЕНТЫ',number:'08 — ESCAPE',title:'Выход на поверхность',desc:'Найдите ближайшую доступную поверхность или верхнее воздушное пространство.',builder:'Быстрый выход',hint:'Команда не требует параметров.',fields:[],build:()=>`surface`}
];

const savedSelections=JSON.parse(localStorage.getItem('baritoneBlocks')||'{}');
const initialCommand=siteSettings.rememberCommand?localStorage.getItem('baritoneLastCommand')||siteSettings.startCommand:siteSettings.startCommand;
const state={active:commands.some(command=>command.id===initialCommand)?initialCommand:'mine',pausedByInstance:new Map(),instances:new Map(),instanceOrder:[],activeInstanceId:null,inventoryTimers:new Map(),inventoryZ:20,scanning:false,blockQuantities:JSON.parse(localStorage.getItem('baritoneBlockQuantities')||'{}'),selectedByCommand:{},draftBlocks:new Set(),values:{},undoByCommand:new Map(),history:JSON.parse(localStorage.getItem('baritoneHistory')||'[]'),errors:JSON.parse(localStorage.getItem('baritoneSiteErrors')||'[]'),lastStatusErrorAt:0,prefix:localStorage.getItem('baritonePrefix')||'#',apiUrl:localStorage.getItem('baritoneApi')||'http://127.0.0.1:8765/api'};
state.alarms=new Set();state.lastHealthByInstance=new Map();
const BASIC_BARITONE_SETTINGS=new Set(['allowBreak','allowSprint','allowPlace','allowInventory','autoTool','allowWaterBucketFall','allowParkour','allowParkourPlace','allowDiagonalDescend','allowDiagonalAscend','allowDownward','maxFallHeightNoWater','blockReachDistance','avoidance','mobAvoidanceRadius','followRadius','chatControl','renderPath','renderGoal','renderSelection']);
const baritoneSettingsUi={scope:'basic',dirty:new Set(),saved:JSON.parse(localStorage.getItem('baritoneGlobalSettings')||'{}')};
for(const commandId of ['mine','find']) state.selectedByCommand[commandId]=new Set(savedSelections[commandId]||[]);
const $=selector=>document.querySelector(selector);
const nav=$('#commandNav');

function current(){return commands.find(command=>command.id===state.active)}
function selected(){return state.selectedByCommand[state.active]||new Set()}
function blockIcon(id,className='selected-block-icon'){const apiUrl=activeInstance()?.apiUrl||state.apiUrl.replace(/\/$/,'');return itemIcon(id,className,apiUrl)}
function itemIcon(id,className='inventory-item-icon',apiUrl='',iconKey=''){const base=apiUrl?apiUrl.replace(/\/$/,''):'';const bridgeSrc=id&&base?(iconKey?`${base}/item-icon?key=${encodeURIComponent(iconKey)}&id=${encodeURIComponent(id)}`:`${base}/item-icon?id=${encodeURIComponent(id)}`):'';if(bridgeSrc)return `<img class="${className}" src="${bridgeSrc}" alt="" loading="lazy" decoding="async" onerror="this.style.display='none'">`;return ''}
function activeInstance(){return state.instances.get(state.activeInstanceId)||null}
function commandApiUrl(){return activeInstance()?.apiUrl||state.apiUrl.replace(/\/$/,'')}
function saveBlocks(){localStorage.setItem('baritoneBlocks',JSON.stringify(Object.fromEntries(Object.entries(state.selectedByCommand).map(([key,value])=>[key,[...value]]))))}
function applySiteSettings(){const body=document.body;document.documentElement.style.setProperty('--sidebar',`${Math.max(190,Math.min(310,Number(siteSettings.sidebarWidth)||220))}px`);document.documentElement.style.setProperty('--green',siteSettings.accent);document.documentElement.style.setProperty('--green2',`color-mix(in srgb, ${siteSettings.accent}, white 35%)`);document.documentElement.style.setProperty('--user-radius',`${siteSettings.corners}px`);body.style.zoom=String(siteSettings.uiScale);body.classList.add('site-customized');body.classList.toggle('site-no-noise',!siteSettings.noise);body.classList.toggle('site-no-animations',!siteSettings.animations);body.classList.toggle('site-compact-players',siteSettings.compactPlayers);body.classList.toggle('site-hide-hints',!siteSettings.showHints);body.classList.toggle('site-hide-api',!siteSettings.showApiNotes);body.classList.toggle('site-hide-history',!siteSettings.showHistory);body.classList.toggle('site-hide-live',!siteSettings.showLiveBadge);body.classList.toggle('site-show-crafting',Boolean(siteSettings.showCrafting));body.classList.toggle('site-density-compact',siteSettings.density==='compact');body.classList.toggle('site-density-spacious',siteSettings.density==='spacious');renderHistory()}
function populateSiteSettings(){const values={siteUiScale:siteSettings.uiScale,siteDensity:siteSettings.density,siteSidebarWidth:siteSettings.sidebarWidth,siteCorners:siteSettings.corners,siteAccent:siteSettings.accent,siteHistoryLimit:siteSettings.historyLimit,siteStartCommand:siteSettings.startCommand};for(const [id,value] of Object.entries(values)){const element=$(`#${id}`);if(element)element.value=String(value)}const checks={siteNoise:'noise',siteAnimations:'animations',siteCompactPlayers:'compactPlayers',siteShowHints:'showHints',siteShowApiNotes:'showApiNotes',siteShowHistory:'showHistory',siteShowLiveBadge:'showLiveBadge',siteShowCrafting:'showCrafting',siteRememberCommand:'rememberCommand',siteConfirmRun:'confirmRun',siteConfirmClear:'confirmClear',siteShortcuts:'shortcuts'};for(const [id,key] of Object.entries(checks)){const element=$(`#${id}`);if(element)element.checked=Boolean(siteSettings[key])}$('#siteSidebarWidthValue').textContent=`${siteSettings.sidebarWidth} px`}
function readSiteSettingsForm(){return {uiScale:Number($('#siteUiScale').value),density:$('#siteDensity').value,sidebarWidth:Number($('#siteSidebarWidth').value),corners:Number($('#siteCorners').value),accent:$('#siteAccent').value,noise:$('#siteNoise').checked,animations:$('#siteAnimations').checked,compactPlayers:$('#siteCompactPlayers').checked,showHints:$('#siteShowHints').checked,showApiNotes:$('#siteShowApiNotes').checked,showHistory:$('#siteShowHistory').checked,showLiveBadge:$('#siteShowLiveBadge').checked,showCrafting:$('#siteShowCrafting')?.checked??Boolean(siteSettings.showCrafting),historyLimit:Number($('#siteHistoryLimit').value),startCommand:$('#siteStartCommand').value,rememberCommand:$('#siteRememberCommand').checked,confirmRun:$('#siteConfirmRun').checked,confirmClear:$('#siteConfirmClear').checked,shortcuts:$('#siteShortcuts').checked}}
function saveSitePreferences(){Object.assign(siteSettings,readSiteSettingsForm());localStorage.setItem('baritoneSiteSettings',JSON.stringify(siteSettings));applySiteSettings();toast('Настройки сайта сохранены')}
function resetSitePreferences(){Object.assign(siteSettings,SITE_SETTINGS_DEFAULTS);localStorage.removeItem('baritoneSiteSettings');populateSiteSettings();applySiteSettings();toast('Настройки сайта сброшены')}
function commandSnapshot(){return {values:{...state.values},blocks:[...selected()],quantities:{...state.blockQuantities}}}
function updateUndoButton(){const button=$('#undoButton');if(button)button.disabled=!(state.undoByCommand.get(state.active)?.length)}
function pushUndo(){const stack=state.undoByCommand.get(state.active)||[];const snapshot=commandSnapshot();const serialized=JSON.stringify(snapshot);if(JSON.stringify(stack.at(-1))!==serialized){stack.push(snapshot);if(stack.length>30)stack.shift();state.undoByCommand.set(state.active,stack)}updateUndoButton()}
function undoCommandChange(){const stack=state.undoByCommand.get(state.active);if(!stack?.length)return;const snapshot=stack.pop();state.values={...snapshot.values};state.selectedByCommand[state.active]=new Set(snapshot.blocks);state.blockQuantities={...snapshot.quantities};saveBlocks();localStorage.setItem('baritoneBlockQuantities',JSON.stringify(state.blockQuantities));renderPage();updateUndoButton();toast('Последнее изменение отменено')}
function renderNav(){let group='';nav.innerHTML=commands.map(command=>{const heading=command.group!==group?`<div class="nav-group">${group=command.group}</div>`:'';const names={goto:'Goto',mine:'Mine',explore:'Explore',farm:'Farm',follow:'Follow',build:'Build',find:'Find',surface:'Surface'};return `${heading}<button class="nav-item ${command.id===state.active?'active':''}" data-command="${command.id}"><span class="nav-icon">${command.icon}</span><span>${names[command.id]}</span></button>`}).join('');nav.querySelectorAll('[data-command]').forEach(button=>button.onclick=()=>selectCommand(button.dataset.command))}
function selectCommand(id){state.active=id;state.values={};if(siteSettings.rememberCommand)localStorage.setItem('baritoneLastCommand',id);renderNav();renderPage();updateUndoButton();$('.sidebar').classList.remove('open')}

function renderPage(){
  const c=current();
  $('#breadcrumb').textContent=c.id.toUpperCase();$('#pageTitle').textContent=c.title;$('#pageDescription').textContent=c.desc;$('#builderTitle').textContent=c.builder;$('#commandHint').textContent=c.hint;$('#apiQuotaNote').hidden=c.id!=='mine';
  const fields=c.fields.map(([id,label,placeholder,size,type='text',options=[]])=>{if(type==='select'){state.values[id]??=options[0]?.[0]||'';return `<div class="field ${size||''}"><label for="f-${id}">${label}</label><select id="f-${id}" data-field="${id}">${options.map(([value,text])=>`<option value="${value}" ${state.values[id]===value?'selected':''}>${text}</option>`).join('')}</select></div>`}return `<div class="field ${size||''}"><label for="f-${id}">${label}</label><input id="f-${id}" data-field="${id}" value="${escapeHtml(state.values[id]||'')}" placeholder="${placeholder}" autocomplete="off"></div>`}).join('');
  const picker=c.blockPicker?`<div class="block-selector"><button class="block-selector-button" id="openBlockPicker" type="button">ВЫБОР БЛОКОВ <span>＋</span></button><div class="selected-blocks" id="selectedBlocks"></div></div>`:'';
  $('#dynamicForm').innerHTML=picker+fields;$('#minePresets').innerHTML='';
  document.querySelectorAll('[data-field]').forEach(input=>{input.onfocus=()=>input.dataset.undoCaptured='';input.onbeforeinput=()=>{if(!input.dataset.undoCaptured){pushUndo();input.dataset.undoCaptured='1'}};input.onchange=()=>{if(!input.dataset.undoCaptured)pushUndo();state.values[input.dataset.field]=input.value.trim();input.dataset.undoCaptured='1';updateOutput()};input.oninput=()=>{state.values[input.dataset.field]=input.value.trim();updateOutput()};input.onblur=()=>delete input.dataset.undoCaptured});
  if(c.blockPicker){$('#openBlockPicker').onclick=openBlockPicker;renderSelectedBlocks()}
  updateOutput();updateUndoButton();
}

function renderSelectedBlocks(){
  const container=$('#selectedBlocks');if(!container)return;
  const ids=[...selected()];
  container.innerHTML=ids.length?ids.map(id=>{const block=CATALOG_BY_ID.get(id)||{name:id,id,kind:'block'};const quantity=state.active==='mine'&&block.kind==='block'?`<input class="block-quantity" data-block-quantity="${escapeHtml(id)}" type="number" min="1" step="1" value="${escapeHtml(state.blockQuantities[id]||'')}" placeholder="∞" aria-label="Количество ${escapeHtml(block.name)}">`:'';return `<div class="selected-block">${quantity}${blockIcon(id,'selected-block-icon')}<div><b>${escapeHtml(block.name)}</b><code>${escapeHtml(block.id)}</code></div><button type="button" data-remove-block="${escapeHtml(id)}" title="Исключить">×</button></div>`}).join(''):'<div class="selected-blocks-empty">Блоки ещё не выбраны</div>';
  container.querySelectorAll('[data-block-quantity]').forEach(input=>{input.onfocus=()=>input.dataset.undoCaptured='';input.onbeforeinput=()=>{if(!input.dataset.undoCaptured){pushUndo();input.dataset.undoCaptured='1'}};input.oninput=()=>{const id=input.dataset.blockQuantity;state.blockQuantities[id]=input.value.trim();localStorage.setItem('baritoneBlockQuantities',JSON.stringify(state.blockQuantities));updateOutput()};input.onblur=()=>delete input.dataset.undoCaptured});
  container.querySelectorAll('[data-remove-block]').forEach(button=>button.onclick=()=>{pushUndo();const id=button.dataset.removeBlock;selected().delete(id);delete state.blockQuantities[id];localStorage.setItem('baritoneBlockQuantities',JSON.stringify(state.blockQuantities));saveBlocks();renderSelectedBlocks();updateOutput()});
}

function openBlockPicker(){state.draftBlocks=new Set(selected());$('#blockSearch').value='';renderBlockCatalog();$('#blockPickerDialog').showModal();setTimeout(()=>$('#blockSearch').focus(),0)}
function renderBlockCatalog(){
  const query=$('#blockSearch').value.trim().toLocaleLowerCase('ru');
  const matches=CATALOG_ITEMS.filter(block=>!query||block.id.includes(query)||block.name.toLocaleLowerCase('ru').includes(query));
  $('#blockSearchCount').textContent=CATALOG_ITEMS.length?`Найдено: ${matches.length} из ${CATALOG_ITEMS.length}`:'Введите ID вручную или дождитесь сканирования Bridge';$('#blockSelectedCount').textContent=`Выбрано: ${state.draftBlocks.size}`;
  const apiUrl=activeInstance()?.apiUrl||state.apiUrl.replace(/\/$/,'');
  $('#blockCatalog').innerHTML=matches.length?matches.map(block=>`<button class="block-card ${state.draftBlocks.has(block.id)?'selected':''}" type="button" data-catalog-block="${escapeHtml(block.id)}"><span class="check">✓</span>${itemIcon(block.id,'block-card-icon',apiUrl)}<span class="block-card-text"><b>${escapeHtml(block.name||block.id)}</b><small>${escapeHtml(block.id)}</small></span></button>`).join(''):'<div class="block-catalog-empty">Например: minecraft:diamond_ore или modid:block_name</div>';
  document.querySelectorAll('[data-catalog-block]').forEach(button=>button.onclick=()=>{const id=button.dataset.catalogBlock;state.draftBlocks.has(id)?state.draftBlocks.delete(id):state.draftBlocks.add(id);button.classList.toggle('selected');$('#blockSelectedCount').textContent=`Выбрано: ${state.draftBlocks.size}`});
}

function command(){return state.prefix+current().build(state.values,selected()).trim()}
function updateOutput(){$('#commandOutput').textContent=command()}
function requestCurrentCommand(){if(siteSettings.confirmRun&&!confirm(`Отправить команду ${command()} игроку ${activeInstance()?.playerName||'—'}?`))return;run()}
function toast(text){const element=$('#toast');element.textContent=text;try{if(element.showPopover&&!element.matches(':popover-open'))element.showPopover()}catch{}element.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>{element.classList.remove('show');try{if(element.hidePopover&&element.matches(':popover-open'))element.hidePopover()}catch{}},5000)}
function addSiteError(type,message,details={}){const entry={id:Date.now()+Math.random(),time:new Date().toISOString(),type,message:String(message||'Неизвестная ошибка'),details};state.errors.unshift(entry);state.errors=state.errors.slice(0,100);localStorage.setItem('baritoneSiteErrors',JSON.stringify(state.errors));updateErrorCount();return entry}
function updateErrorCount(){const count=$('#errorLogCount');count.textContent=String(state.errors.length);count.dataset.count=String(state.errors.length)}
function renderErrorLog(){const list=$('#errorLogList');list.innerHTML=state.errors.length?state.errors.map(entry=>{const details=Object.entries(entry.details||{}).filter(([,value])=>value!==undefined&&value!=='').map(([key,value])=>`${key}: ${value}`).join('\n');return `<article class="error-entry"><div class="error-entry-meta"><span class="error-entry-type">${escapeHtml(entry.type)}</span><time>${new Date(entry.time).toLocaleString('ru-RU')}</time></div><pre class="error-entry-message">${escapeHtml(entry.message)}${details?`\n${escapeHtml(details)}`:''}</pre></article>`}).join(''):'<div class="error-log-empty">Ошибок сайта пока нет.</div>'}
async function run(action,targetInstanceId=null){
  if(!action){const validation=current().validate?.(state.values,selected());if(validation){toast(validation);return false}}
  const targetInstance=targetInstanceId?state.instances.get(targetInstanceId):activeInstance();
  const cmd=action||command();const endpoint=`${targetInstance?.apiUrl||commandApiUrl()}/command`;
  try{
    const response=await fetch(endpoint,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({command:cmd})});
    const data=await response.json().catch(()=>({}));
    if(!response.ok){const requestId=data.requestId||response.headers.get('X-Baritone-Bridge-Request-Id');const failure=new Error(`${data.error||`HTTP ${response.status}`}${requestId?` [request ${requestId}]`:''}`);failure.requestId=requestId;failure.status=response.status;throw failure}
    state.history.unshift({cmd,playerName:targetInstance?.playerName||'—',time:new Date().toLocaleTimeString('ru-RU',{hour:'2-digit',minute:'2-digit'}),status:`выполнено · #${data.requestId||'—'}`});state.history=state.history.slice(0,20);localStorage.setItem('baritoneHistory',JSON.stringify(state.history));renderHistory();toast(`Команда отправлена игроку ${targetInstance?.playerName||''} · request ${data.requestId||'—'}`);if(!targetInstanceId||targetInstanceId===state.activeInstanceId)setConnection(true,data.inGame);return true
  }catch(error){if(!targetInstanceId||targetInstanceId===state.activeInstanceId)setConnection(false);addSiteError('bridge-command',error.message,{command:cmd,endpoint,status:error.status,requestId:error.requestId});toast(`Bridge: ${error.message||'нет подключения'}`);return false}
}
function renderPauseControls(){const hasPlayer=Boolean(state.activeInstanceId&&state.instances.has(state.activeInstanceId));const paused=hasPlayer&&state.pausedByInstance.get(state.activeInstanceId)===true;$('#pauseButton').disabled=!hasPlayer||paused;$('#resumeButton').disabled=!hasPlayer||!paused;$('#stopButton').disabled=!hasPlayer;document.querySelectorAll('.inventory-window').forEach(windowElement=>{const instanceId=windowElement.dataset.inventoryInstance;const windowPaused=state.pausedByInstance.get(instanceId)===true;windowElement.querySelector('[data-inventory-control="resume"]')?.toggleAttribute('disabled',!windowPaused);windowElement.querySelector('[data-inventory-control="pause"]')?.toggleAttribute('disabled',windowPaused)})}
function setConnection(online,inGame=true){$('.connection-card').classList.toggle('online',online);$('#connectionText').textContent=online?(inGame===false?'Откройте мир':'Подключено'):'Ожидает подключения'}
function renderInstances(){const list=$('#instanceList');const instances=state.instanceOrder.map(id=>state.instances.get(id)).filter(Boolean);$('#instanceCount').textContent=String(instances.length);list.innerHTML=instances.length?instances.map(instance=>`<div class="instance-card ${instance.instanceId===state.activeInstanceId?'active':''}"><button class="instance-button" type="button" data-instance-id="${escapeHtml(instance.instanceId)}"><span class="status-dot"></span><span><b>${escapeHtml(instance.playerName||'Без имени')}</b><small><span class="instance-port">порт ${instance.port}</span><span class="instance-separator"> · </span><span class="instance-location">${instance.inGame?'в мире':'в меню'}</span></small></span><i>›</i></button><button class="instance-inventory-button" type="button" data-inventory-id="${escapeHtml(instance.instanceId)}" title="Открыть инвентарь ${escapeHtml(instance.playerName||'игрока')}" aria-label="Открыть инвентарь ${escapeHtml(instance.playerName||'игрока')}"><span>▦</span><small>ИНВЕНТАРЬ</small></button></div>`).join(''):'<div class="instance-empty">Запущенные клиенты не найдены</div>';list.querySelectorAll('[data-instance-id]').forEach(button=>button.onclick=()=>selectInstance(button.dataset.instanceId));list.querySelectorAll('[data-inventory-id]').forEach(button=>button.onclick=()=>selectInstance(button.dataset.inventoryId,true))}
function selectInstance(instanceId,openInventory=false){if(!state.instances.has(instanceId))return;if(openInventory){openInventoryDialog(instanceId);return}state.activeInstanceId=instanceId;renderPauseControls();renderInstances();const instance=activeInstance();setConnection(true,instance.inGame)}
function bridgeScanUrls(){try{const configured=new URL(state.apiUrl);const host=configured.hostname||'127.0.0.1';return Array.from({length:31},(_,index)=>`${configured.protocol}//${host}:${8765+index}/api`)}catch{return Array.from({length:31},(_,index)=>`http://127.0.0.1:${8765+index}/api`)}}
async function probeBridge(apiUrl){try{const response=await fetch(`${apiUrl}/status`,{cache:'no-store',signal:AbortSignal.timeout(900)});if(!response.ok)return null;const data=await response.json();if(!data.online||!data.instanceId)return null;const health=Number(data.health),previous=state.lastHealthByInstance.get(data.instanceId),command=String(data.lastCommand||'').trim(),activeCommand=command&&!/^#(cancel|stop|pause|resume)\b/i.test(command);if(siteSettings.attackAlarm&&data.inGame&&activeCommand&&Number.isFinite(health)&&Number.isFinite(previous)&&health<previous-0.1)triggerAttackAlarm(data.instanceId);if(Number.isFinite(health))state.lastHealthByInstance.set(data.instanceId,health);return {...data,apiUrl}}catch{return null}}
async function checkBridge(){if(state.scanning)return;state.scanning=true;try{const found=(await Promise.all(bridgeScanUrls().map(probeBridge))).filter(Boolean);const foundIds=new Set(found.map(instance=>instance.instanceId));state.instanceOrder=state.instanceOrder.filter(id=>foundIds.has(id));for(const instance of found)if(!state.instanceOrder.includes(instance.instanceId))state.instanceOrder.push(instance.instanceId);state.instances=new Map(found.map(instance=>[instance.instanceId,instance]));if(!state.instances.has(state.activeInstanceId))state.activeInstanceId=(found.find(instance=>instance.inGame)||found[0])?.instanceId||null;renderInstances();renderPauseControls();const instance=activeInstance();setConnection(Boolean(instance),instance?.inGame);if(!instance){const now=Date.now();if(now-state.lastStatusErrorAt>30000){state.lastStatusErrorAt=now;addSiteError('bridge-status','Не найдено ни одного запущенного bridge',{ports:'8765–8795'})}}}finally{state.scanning=false}}
function inventorySlotLabel(slot){if(slot<9)return `Панель ${slot+1}`;if(slot<36)return `Слот ${slot-8}`;return ['Ботинки','Поножи','Нагрудник','Шлем','2я рука'][slot-36]||`Слот ${slot}`}
function inventorySlotMarkup(slot,label=inventorySlotLabel(slot.slot),apiUrl=''){const actionable=Number.isInteger(slot.handlerSlot)&&slot.handlerSlot>=0;const help=slot.id&&actionable?' · Перетащить: переместить · двойной клик: быстрый перенос · ПКМ: выбросить один · Shift+ПКМ: выбросить пачку · клавиши 1–9: обмен с хотбаром':'';return `<div class="inventory-slot ${slot.id?'filled':'empty'}" ${actionable?`data-handler-slot="${slot.handlerSlot}"`:''} ${slot.id&&actionable?'draggable="true" tabindex="0"':''} title="${escapeHtml((slot.name||label)+help)}">${slot.id?itemIcon(slot.id,'inventory-item-icon',apiUrl,slot.iconKey||''):''}${slot.count>1?`<b>${slot.count}</b>`:''}<small>${escapeHtml(label)}</small>${slot.maxDamage>0?`<span class="durability"><i style="width:${Math.max(0,100-slot.damage/slot.maxDamage*100)}%"></i></span>`:''}</div>`}
function hudIcons(value,max,symbol,className){const count=10,perIcon=max/count;return Array.from({length:count},(_,index)=>{const remaining=value-index*perIcon;const state=remaining>=perIcon?'full':remaining>0?'half':'empty';return `<i class="${className} ${state}">${symbol}</i>`}).join('')}
function playerHudMarkup(data){const health=Number(data.health||0),maxHealth=Number(data.maxHealth||20),food=Number(data.food||0),armor=Number(data.armor||0),level=Number(data.experienceLevel||0),progress=Math.max(0,Math.min(100,Number(data.experienceProgress||0)*100));return `<div class="player-hud"><div class="hud-row"><div class="hud-stat armor-stat" title="Броня: ${armor}/20"><b>${armor}</b><span>${hudIcons(armor,20,'◆','armor-icon')}</span></div><div class="hud-stat health-stat" title="Здоровье: ${health}/${maxHealth}"><b>${Math.ceil(health)}/${Math.ceil(maxHealth)}</b><span>${hudIcons(health,maxHealth,'♥','heart-icon')}</span></div><div class="hud-stat food-stat" title="Голод: ${food}/20"><b>${food}/20</b><span>${hudIcons(food,20,'●','food-icon')}</span></div></div><div class="experience-bar" title="Уровень ${level} · ${Math.round(progress)}%"><i style="width:${progress}%"></i><b>${level}</b></div></div>`}
function renderInventory(data,windowElement){if(windowElement.dataset.inventoryDragging==='true')return;windowElement.querySelector('[data-inventory-title]').textContent=`Инвентарь — ${data.playerName}`;windowElement.querySelector('[data-inventory-endpoint]').textContent=`127.0.0.1:${data.port}`;windowElement.querySelector('[data-inventory-updated]').textContent=`Обновлено ${new Date().toLocaleTimeString('ru-RU')}`;const instance=state.instances.get(windowElement.dataset.inventoryInstance);const iconApiUrl=instance?.apiUrl||`http://127.0.0.1:${data.port}/api`;const bySlot=new Map(data.slots.map(slot=>[slot.slot,slot]));const renderSlots=ids=>ids.map(id=>inventorySlotMarkup(bySlot.get(id)||{slot:id,handlerSlot:-1},undefined,iconApiUrl)).join('');const container=data.container?.slots?.length?`<section class="inventory-container"><div class="inventory-container-title">${escapeHtml(data.container.title||'Открытый контейнер')}</div><div class="inventory-container-grid">${data.container.slots.map((slot,index)=>inventorySlotMarkup(slot,`Яч. ${index+1}`,iconApiUrl)).join('')}</div></section>`:'';windowElement.querySelector('[data-inventory-slots]').innerHTML=`<div class="inventory-storage"><div class="inventory-main-grid">${renderSlots(Array.from({length:27},(_,index)=>index+9))}</div><div class="inventory-hotbar-grid">${renderSlots(Array.from({length:9},(_,index)=>index))}</div>${playerHudMarkup(data)}${container}</div><aside class="inventory-equipment"><div class="inventory-armor-grid">${renderSlots([39,38,37,36])}</div><div class="inventory-offhand">${renderSlots([40])}</div></aside>`;bindInventoryInteractions(windowElement)}

async function sendInventoryAction(instanceId,payload){const instance=state.instances.get(instanceId);if(!instance)return false;try{const response=await fetch(`${instance.apiUrl}/inventory/action`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});const data=await response.json().catch(()=>({}));if(!response.ok)throw new Error(data.error||`HTTP ${response.status}`);await refreshInventory(instanceId);return true}catch(error){addSiteError('inventory-action',error.message,{player:instance.playerName,action:payload.action});toast(`Инвентарь ${instance.playerName}: ${error.message}`);return false}}
function bindInventoryInteractions(windowElement){const instanceId=windowElement.dataset.inventoryInstance;windowElement.querySelectorAll('.inventory-slot[data-handler-slot]').forEach(slot=>{const handlerSlot=Number(slot.dataset.handlerSlot);if(!Number.isInteger(handlerSlot))return;slot.ondragstart=event=>{if(!slot.classList.contains('filled')){event.preventDefault();return}windowElement.dataset.inventoryDragging='true';event.dataTransfer.effectAllowed='move';event.dataTransfer.setData('text/plain',String(handlerSlot));slot.classList.add('drag-source')};slot.ondragend=()=>{delete windowElement.dataset.inventoryDragging;slot.classList.remove('drag-source')};slot.ondragover=event=>{event.preventDefault();event.dataTransfer.dropEffect='move';slot.classList.add('drag-target')};slot.ondragleave=()=>slot.classList.remove('drag-target');slot.ondrop=async event=>{event.preventDefault();slot.classList.remove('drag-target');const fromSlot=Number(event.dataTransfer.getData('text/plain'));delete windowElement.dataset.inventoryDragging;if(Number.isInteger(fromSlot)&&fromSlot!==handlerSlot)await sendInventoryAction(instanceId,{action:'move',fromSlot,toSlot:handlerSlot})};slot.ondblclick=()=>slot.classList.contains('filled')&&sendInventoryAction(instanceId,{action:'quick_move',fromSlot:handlerSlot});slot.oncontextmenu=event=>{if(!slot.classList.contains('filled'))return;event.preventDefault();sendInventoryAction(instanceId,{action:event.shiftKey?'drop_stack':'drop_one',fromSlot:handlerSlot})};slot.onkeydown=event=>{if(!slot.classList.contains('filled')||!/^Digit[1-9]$/.test(event.code))return;event.preventDefault();sendInventoryAction(instanceId,{action:'swap_hotbar',fromSlot:handlerSlot,hotbarSlot:Number(event.code.at(-1))-1})}})}
async function refreshInventory(instanceId){const instance=state.instances.get(instanceId);const windowElement=document.querySelector(`.inventory-window[data-inventory-instance="${CSS.escape(instanceId)}"]`);if(!instance||!windowElement)return;try{const response=await fetch(`${instance.apiUrl}/inventory`,{cache:'no-store',signal:AbortSignal.timeout(1800)});if(!response.ok)throw new Error(`HTTP ${response.status}`);const data=await response.json();if(data.instanceId===instanceId&&windowElement.isConnected)renderInventory(data,windowElement)}catch(error){const updated=windowElement.querySelector('[data-inventory-updated]');if(updated)updated.textContent=`Нет данных: ${error.message}`}}
function raiseInventoryWindow(windowElement){windowElement.style.zIndex=String(++state.inventoryZ);const rect=windowElement.getBoundingClientRect();const margin=12;if(rect.right<margin||rect.left>innerWidth-margin||rect.bottom<margin||rect.top>innerHeight-margin){windowElement.style.left='50%';windowElement.style.top='92px';windowElement.style.right='auto';windowElement.style.transform='translateX(-50%)'}else{const x=Math.min(Math.max(rect.left,margin),Math.max(margin,innerWidth-rect.width-margin));const y=Math.min(Math.max(rect.top,margin),Math.max(margin,innerHeight-rect.height-margin));windowElement.style.left=`${x}px`;windowElement.style.top=`${y}px`;windowElement.style.transform='none'}}
function enableInventoryDrag(windowElement){const handle=windowElement.querySelector('.inventory-drag-handle');handle.addEventListener('pointerdown',event=>{if(event.target.closest('button'))return;raiseInventoryWindow(windowElement);const rect=windowElement.getBoundingClientRect();const offsetX=event.clientX-rect.left,offsetY=event.clientY-rect.top;windowElement.style.left=`${rect.left}px`;windowElement.style.top=`${rect.top}px`;windowElement.style.right='auto';windowElement.style.transform='none';handle.setPointerCapture(event.pointerId);const move=moveEvent=>{const maxX=Math.max(0,innerWidth-windowElement.offsetWidth);const maxY=Math.max(0,innerHeight-windowElement.offsetHeight);windowElement.style.left=`${Math.min(maxX,Math.max(0,moveEvent.clientX-offsetX))}px`;windowElement.style.top=`${Math.min(maxY,Math.max(0,moveEvent.clientY-offsetY))}px`};const end=()=>{handle.removeEventListener('pointermove',move);handle.removeEventListener('pointerup',end);handle.removeEventListener('pointercancel',end)};handle.addEventListener('pointermove',move);handle.addEventListener('pointerup',end);handle.addEventListener('pointercancel',end)})}
function closeInventoryWindow(instanceId){const timer=state.inventoryTimers.get(instanceId);if(timer)clearInterval(timer);state.inventoryTimers.delete(instanceId);document.querySelector(`.inventory-window[data-inventory-instance="${CSS.escape(instanceId)}"]`)?.remove()}
function openInventoryDialog(instanceId=state.activeInstanceId){const instance=state.instances.get(instanceId);if(!instance)return;let windowElement=document.querySelector(`.inventory-window[data-inventory-instance="${CSS.escape(instanceId)}"]`);if(windowElement){raiseInventoryWindow(windowElement);return}windowElement=document.createElement('section');windowElement.className='inventory-window';windowElement.dataset.inventoryInstance=instanceId;windowElement.style.setProperty('--inventory-offset',`${state.inventoryTimers.size*26}px`);windowElement.innerHTML=`<div class="inventory-shell"><div class="inventory-drag-handle"><div class="inventory-header-main"><h2 data-inventory-title>Инвентарь — ${escapeHtml(instance.playerName)}</h2><div class="inventory-header-meta"><span data-inventory-endpoint>127.0.0.1:${instance.port}</span><span class="inventory-update"><i class="status-dot"></i><span data-inventory-updated>Ожидание данных</span></span></div></div><div class="inventory-mini-controls"><button type="button" data-inventory-control="resume" title="Продолжить">▶</button><button type="button" data-inventory-control="pause" title="Пауза">Ⅱ</button><button type="button" data-inventory-control="stop" title="Стоп">■</button></div><button class="dialog-close" type="button" aria-label="Закрыть">×</button></div><div class="inventory-slots" data-inventory-slots><div class="inventory-loading">Загрузка инвентаря…</div></div></div>`;$('#inventoryWindows').append(windowElement);raiseInventoryWindow(windowElement);enableInventoryDrag(windowElement);windowElement.addEventListener('pointerdown',()=>raiseInventoryWindow(windowElement));windowElement.querySelector('.dialog-close').onclick=()=>closeInventoryWindow(instanceId);windowElement.querySelectorAll('[data-inventory-control]').forEach(button=>button.onclick=()=>runPlayerControl(instanceId,button.dataset.inventoryControl));renderPauseControls();refreshInventory(instanceId);state.inventoryTimers.set(instanceId,setInterval(()=>refreshInventory(instanceId),750))}
async function runPlayerControl(instanceId,action){const commands={resume:'resume',pause:'pause',stop:'cancel'};if(!commands[action]||!state.instances.has(instanceId))return;if(await run(state.prefix+commands[action],instanceId)){state.pausedByInstance.set(instanceId,action==='pause');renderPauseControls()}}
function renderHistory(){const visible=state.history.slice(0,Number(siteSettings.historyLimit)||8);$('#history').innerHTML=visible.length?visible.map(item=>`<div class="history-item"><time>${item.time}</time><b class="history-player">${escapeHtml(item.playerName||'—')}</b><code>${escapeHtml(item.cmd)}</code><span>${item.status}</span></div>`).join(''):'<div class="history-empty">Команд пока нет — запустите первую задачу.</div>'}
function escapeHtml(text){return String(text).replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]))}

