$('#copyButton').onclick=async()=>{await navigator.clipboard.writeText(command());toast('Команда скопирована')};$('#runButton').onclick=requestCurrentCommand;$('#stopButton').onclick=async()=>{const instanceId=state.activeInstanceId;if(instanceId&&await run(state.prefix+'cancel')){state.pausedByInstance.set(instanceId,false);if(state.activeInstanceId===instanceId)renderPauseControls()}};$('#pauseButton').onclick=async()=>{const instanceId=state.activeInstanceId;if(instanceId&&await run(state.prefix+'pause')){state.pausedByInstance.set(instanceId,true);if(state.activeInstanceId===instanceId)renderPauseControls()}};$('#resumeButton').onclick=async()=>{const instanceId=state.activeInstanceId;if(instanceId&&await run(state.prefix+'resume')){state.pausedByInstance.set(instanceId,false);if(state.activeInstanceId===instanceId)renderPauseControls()}};
