function settingValue(setting){return baritoneSettingsUi.saved[setting.name]??setting.defaultValue}
function renderBaritoneSettings(){const query=$('#baritoneSettingsSearch').value.trim().toLowerCase();const category=$('#baritoneSettingsCategory').value;const matches=BARITONE_SETTINGS.filter(setting=>{const translated=BARITONE_DESCRIPTIONS_RU[setting.name]||'';return(baritoneSettingsUi.scope==='all'||BASIC_BARITONE_SETTINGS.has(setting.name))&&(category==='all'||setting.category===category)&&(!query||`${setting.name} ${translated} ${setting.description} ${setting.category}`.toLowerCase().includes(query))});$('#baritoneSettingsCount').textContent=`Показано: ${matches.length} из ${BARITONE_SETTINGS.length} · изменено: ${baritoneSettingsUi.dirty.size}`;$('#baritoneSettingsCatalog').innerHTML=matches.map(setting=>{const value=settingValue(setting);const isBoolean=setting.type==='Boolean';const control=isBoolean?`<input type="checkbox" data-baritone-setting="${setting.name}" ${String(value)==='true'?'checked':''}>`:`<input type="text" data-baritone-setting="${setting.name}" value="${escapeHtml(value)}" placeholder="Введите значение">`;const description=BARITONE_DESCRIPTIONS_RU[setting.name]||setting.description||'Описание отсутствует в исходниках Baritone.';return `<article class="catalog-setting ${baritoneSettingsUi.dirty.has(setting.name)?'changed':''}"><div class="catalog-setting-copy"><b>${setting.name}</b><span>${setting.category} · ${escapeHtml(setting.type)}</span><p>${escapeHtml(description)}</p></div><div class="catalog-setting-control">${control}<button type="button" data-reset-setting="${setting.name}" ${setting.defaultValue===''?'disabled':''} title="Вернуть значение по умолчанию">↺</button></div></article>`}).join('')||'<div class="settings-empty">Настройки не найдены.</div>';document.querySelectorAll('[data-baritone-setting]').forEach(input=>input.onchange=()=>{const setting=BARITONE_SETTINGS.find(item=>item.name===input.dataset.baritoneSetting);baritoneSettingsUi.saved[setting.name]=input.type==='checkbox'?input.checked:input.value;baritoneSettingsUi.dirty.add(setting.name);renderBaritoneSettings()});document.querySelectorAll('[data-reset-setting]').forEach(button=>button.onclick=()=>{const setting=BARITONE_SETTINGS.find(item=>item.name===button.dataset.resetSetting);baritoneSettingsUi.saved[setting.name]=setting.defaultValue;baritoneSettingsUi.dirty.add(setting.name);renderBaritoneSettings()})}
function loadBaritoneSettings(){const categorySelect=$('#baritoneSettingsCategory');if(categorySelect.options.length===1)[...new Set(BARITONE_SETTINGS.map(setting=>setting.category))].sort((a,b)=>a.localeCompare(b,'ru')).forEach(category=>categorySelect.add(new Option(category,category)));$('#baritoneSettingsTargets').textContent=`Аккаунтов найдено: ${state.instances.size}`;const playerSelect=$('#baritoneSettingsPlayer');playerSelect.innerHTML=state.instanceOrder.map(id=>state.instances.get(id)).filter(Boolean).map(instance=>`<option value="${escapeHtml(instance.instanceId)}" ${instance.instanceId===state.activeInstanceId?'selected':''}>${escapeHtml(instance.playerName)} · порт ${instance.port}</option>`).join('');playerSelect.disabled=!playerSelect.options.length;$('#applyPlayerBaritoneSettings').disabled=!playerSelect.options.length;renderBaritoneSettings()}
function settingsBridgeInstance(){const instance=activeInstance();if(!instance)toast('Сначала выберите подключённый аккаунт');return instance}
async function saveBaritoneWebConfig(showToast=true){const instance=settingsBridgeInstance();if(!instance)return false;try{const config={version:1,sourcePlayer:instance.playerName,savedAt:new Date().toISOString(),settings:baritoneSettingsUi.saved};const response=await fetch(`${instance.apiUrl}/web-config`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(config)});const data=await response.json();if(!response.ok)throw new Error(data.error||`HTTP ${response.status}`);$('#baritoneConfigPath').textContent=`Файл: ${data.configPath}`;localStorage.setItem('baritoneGlobalSettings',JSON.stringify(baritoneSettingsUi.saved));if(showToast)toast('Веб-конфиг сохранён рядом с конфигами мода');return true}catch(error){addSiteError('bridge-config-save',error.message,{endpoint:`${instance.apiUrl}/web-config`});toast(`Не удалось сохранить конфиг: ${error.message}`);return false}}
async function readLiveBaritoneSettings(){const instance=settingsBridgeInstance();if(!instance)return;const button=$('#readLiveBaritoneSettings');button.disabled=true;try{const response=await fetch(`${instance.apiUrl}/settings`,{cache:'no-store'});const data=await response.json();if(!response.ok)throw new Error(data.error||`HTTP ${response.status}`);baritoneSettingsUi.saved={...data.settings};baritoneSettingsUi.dirty.clear();localStorage.setItem('baritoneGlobalSettings',JSON.stringify(baritoneSettingsUi.saved));$('#baritoneConfigPath').textContent=`Источник: ${instance.playerName} · ${data.configPath}`;renderBaritoneSettings();await saveBaritoneWebConfig(false);toast(`Считано ${Object.keys(data.settings).length} настроек с ${instance.playerName}`)}catch(error){addSiteError('bridge-settings-read',error.message,{endpoint:`${instance.apiUrl}/settings`});toast(`Не удалось считать настройки: ${error.message}`)}finally{button.disabled=false}}
async function loadBaritoneWebConfig(){const instance=settingsBridgeInstance();if(!instance)return;try{const response=await fetch(`${instance.apiUrl}/web-config`,{cache:'no-store'});const data=await response.json();if(!response.ok)throw new Error(data.error||`HTTP ${response.status}`);baritoneSettingsUi.saved={...(data.config?.settings||{})};baritoneSettingsUi.dirty.clear();localStorage.setItem('baritoneGlobalSettings',JSON.stringify(baritoneSettingsUi.saved));$('#baritoneConfigPath').textContent=`Файл: ${data.configPath}`;renderBaritoneSettings();toast(`Веб-конфиг загружен: ${Object.keys(baritoneSettingsUi.saved).length} настроек`)}catch(error){addSiteError('bridge-config-load',error.message,{endpoint:`${instance.apiUrl}/web-config`});toast(`Не удалось загрузить конфиг: ${error.message}`)}}
document.querySelectorAll('[data-settings-tab]').forEach(button=>button.onclick=()=>selectSettingsTab(button.dataset.settingsTab));
$('#baritoneSettingsSearch').oninput=renderBaritoneSettings;$('#baritoneSettingsCategory').onchange=renderBaritoneSettings;document.querySelectorAll('[data-settings-scope]').forEach(button=>button.onclick=()=>{baritoneSettingsUi.scope=button.dataset.settingsScope;document.querySelectorAll('[data-settings-scope]').forEach(item=>item.classList.toggle('active',item===button));renderBaritoneSettings()});$('#resetChangedSettings').onclick=()=>{baritoneSettingsUi.saved=JSON.parse(localStorage.getItem('baritoneGlobalSettings')||'{}');baritoneSettingsUi.dirty.clear();renderBaritoneSettings()};
$('#readLiveBaritoneSettings').onclick=readLiveBaritoneSettings;$('#loadBaritoneWebConfig').onclick=loadBaritoneWebConfig;$('#saveBaritoneWebConfig').onclick=()=>saveBaritoneWebConfig();
document.querySelector('[data-action=settings]').onclick=()=>{ensureCraftingSetting();$('#apiUrl').value=state.apiUrl;$('#commandPrefix').value=state.prefix;try{loadBaritoneSettings()}catch(error){addSiteError('settings-load',error.message);toast(`Не удалось загрузить каталог настроек: ${error.message}`)}try{populateSiteSettings()}catch(error){addSiteError('site-settings-load',error.message);toast(`Не удалось загрузить настройки сайта: ${error.message}`)}selectSettingsTab('baritone');const dialog=$('#settingsDialog');if(dialog&&!dialog.open)dialog.showModal()};
async function applyChangedBaritoneSettings(instances,button,restingText,clearAfterSuccess){if(!instances.length){toast('Нет подключённых аккаунтов');return}const changed=[...baritoneSettingsUi.dirty].map(name=>[name,baritoneSettingsUi.saved[name]]).filter(([,value])=>value!==''&&value!==undefined);if(!changed.length){toast('Нет изменённых настроек');return}button.disabled=true;button.textContent='ПРИМЕНЕНИЕ…';let applied=0,failed=0;for(const instance of instances){let success=true;for(const [name,value] of changed){if(!await run(`${state.prefix}set ${name} ${value}`,instance.instanceId)){success=false;break}}success?applied++:failed++}if(!failed){localStorage.setItem('baritoneGlobalSettings',JSON.stringify(baritoneSettingsUi.saved));if(clearAfterSuccess)baritoneSettingsUi.dirty.clear()}button.disabled=false;button.textContent=restingText;renderBaritoneSettings();toast(`Настройки применены: ${applied}${failed?` · ошибок: ${failed}`:''}`)}
$('#applyBaritoneSettings').onclick=()=>applyChangedBaritoneSettings([...state.instances.values()],$('#applyBaritoneSettings'),'ПРИМЕНИТЬ ДЛЯ ВСЕХ',true);
$('#applyPlayerBaritoneSettings').onclick=()=>{const instance=state.instances.get($('#baritoneSettingsPlayer').value);if(!instance){toast('Выбранный игрок недоступен');return}applyChangedBaritoneSettings([instance],$('#applyPlayerBaritoneSettings'),'ПРИМЕНИТЬ ДЛЯ ИГРОКА',false)};
$('#saveSettings').onclick=()=>{state.apiUrl=$('#apiUrl').value.trim();state.prefix=$('#commandPrefix').value||'#';localStorage.setItem('baritoneApi',state.apiUrl);localStorage.setItem('baritonePrefix',state.prefix);updateOutput();checkBridge();toast('Настройки Bridge сохранены')};
$('#saveSiteSettings').onclick=saveSitePreferences;$('#resetSiteSettings').onclick=resetSitePreferences;$('#siteSidebarWidth').oninput=event=>$('#siteSidebarWidthValue').textContent=`${event.target.value} px`;
window.addEventListener('error',event=>addSiteError('javascript',event.message,{file:event.filename,line:event.lineno,column:event.colno}));
window.addEventListener('unhandledrejection',event=>addSiteError('promise',event.reason?.stack||event.reason?.message||String(event.reason)));
document.addEventListener('keydown',event=>{if(siteSettings.shortcuts&&event.ctrlKey&&event.key==='Enter'&&!$('#blockPickerDialog').open)requestCurrentCommand()});
function ensureCraftingSetting(){const host=$('#siteShortcuts')?.closest('.site-toggle-grid');if(!host)return;const add=(id,text,key)=>{if($(`#${id}`))return;const label=document.createElement('label');label.innerHTML=`<input id="${id}" type="checkbox"> ${text}`;host.prepend(label);$(`#${id}`).checked=Boolean(siteSettings[key]);$(`#${id}`).onchange=()=>{siteSettings[key]=$(`#${id}`).checked;document.body.classList.toggle('site-hide-crafting',!siteSettings.showCrafting);localStorage.setItem('baritoneSiteSettings',JSON.stringify(siteSettings));applyAlarmVisuals()}};add('siteShowCrafting','Показывать сундуки и другие контейнеры','showCrafting');add('siteAttackAlarm','Включить тревогу при атаке','attackAlarm');add('siteAttackAutoPause','Автоматически ставить Baritone на паузу','attackAutoPause');document.body.classList.toggle('site-hide-crafting',!siteSettings.showCrafting)}
const originalSettingsOpen=document.querySelector('[data-action=settings]');originalSettingsOpen?.addEventListener('click',()=>setTimeout(ensureCraftingSetting,0));
originalSettingsOpen?.addEventListener('click',()=>{const dialog=$('#settingsDialog');if(dialog&&!dialog.open){try{dialog.showModal()}catch{dialog.setAttribute('open','')}}});
function formatCacheSize(bytes){return `${(Number(bytes||0)/1048576).toFixed(Number(bytes||0)>=10485760?0:1)} МБ`}
function installCacheControls(){const settingsButton=document.querySelector('[data-action=settings]');if(!settingsButton||$('#cacheFolderButton'))return;const row=document.createElement('div');row.className='cache-tools';row.innerHTML='<button class="nav-item cache-folder-button" id="cacheFolderButton" type="button"><span class="nav-icon">▣</span><span id="cacheSizeText">0 МБ</span></button><span class="cache-help" tabindex="0">?<span class="cache-help-popup">Кеш содержит PNG-иконки, которые Bridge отрисовал через Minecraft для текущей модовой сборки. Он ускоряет повторное открытие инвентаря. Нажмите кнопку, чтобы открыть папку. Для очистки закройте Minecraft и удалите содержимое этой папки — нужные иконки будут созданы заново.</span></span>';settingsButton.after(row);$('#cacheFolderButton').onclick=openCacheFolder}
function cacheApiUrl(){return activeInstance()?.apiUrl||state.apiUrl.replace(/\/$/,'')}
async function refreshCacheInfo(){try{const response=await fetch(`${cacheApiUrl()}/cache`,{cache:'no-store',signal:AbortSignal.timeout(1800)});if(!response.ok)return;const data=await response.json();if($('#cacheSizeText'))$('#cacheSizeText').textContent=formatCacheSize(data.bytes)}catch{}}
async function loadBridgeCatalog(){const instance=activeInstance();if(!instance||state.catalogInstanceId===instance.instanceId&&CATALOG_ITEMS.length)return;try{const response=await fetch(`${instance.apiUrl}/catalog`,{cache:'no-store',signal:AbortSignal.timeout(10000)});if(!response.ok)throw new Error(`HTTP ${response.status}`);const data=await response.json();const blocks=(data.blocks||[]).map(entry=>typeof entry==='string'?{id:entry,name:entry,kind:'block'}:{id:entry.id,name:entry.name||entry.id,kind:'block'});CATALOG_ITEMS=blocks;CATALOG_BY_ID.clear();for(const block of blocks)CATALOG_BY_ID.set(block.id,block);state.catalogInstanceId=instance.instanceId;localStorage.setItem('baritoneBridgeCatalog',JSON.stringify({fingerprint:data.fingerprint,blocks}));renderBlockCatalog()}catch(error){try{const saved=JSON.parse(localStorage.getItem('baritoneBridgeCatalog')||'{}');if(saved.blocks?.length){CATALOG_ITEMS=saved.blocks;CATALOG_BY_ID.clear();for(const block of CATALOG_ITEMS)CATALOG_BY_ID.set(block.id,block);renderBlockCatalog()}}catch{}}}
async function openCacheFolder(){try{const response=await fetch(`${cacheApiUrl()}/cache/open`,{method:'POST',signal:AbortSignal.timeout(2500)});if(!response.ok)throw new Error(`HTTP ${response.status}`);toast('Папка кеша открыта')}catch(error){toast(`Не удалось открыть кеш: запустите Minecraft с Bridge (${error.message})`)}}
installCacheControls();applySiteSettings();document.body.classList.toggle('site-hide-crafting',!siteSettings.showCrafting);renderNav();renderPage();renderHistory();updateErrorCount();renderPauseControls();checkBridge().then(()=>{refreshCacheInfo();loadBridgeCatalog()});setInterval(()=>{checkBridge().then(()=>{refreshCacheInfo();loadBridgeCatalog()})},10000);
// Attack alarm: health loss in an open inventory starts a persistent visual alert.
function triggerAttackAlarm(instanceId){if(!siteSettings.attackAlarm||state.alarms.has(instanceId))return;state.alarms.add(instanceId);const instance=state.instances.get(instanceId);if(siteSettings.attackAutoPause&&instance?.inGame)runPlayerControl(instanceId,'pause');toast(`ТРЕВОГА: ${instance?.playerName||'Игрок'} атакован`);applyAlarmVisuals()}
function dismissAttackAlarms(){state.alarms.clear();applyAlarmVisuals();toast('Тревога отключена')}
function applyAlarmVisuals(){document.querySelectorAll('.inventory-window').forEach(el=>el.classList.toggle('under-attack',state.alarms.has(el.dataset.inventoryInstance)));document.querySelectorAll('.instance-card').forEach(el=>{const button=el.querySelector('[data-instance-id]');el.classList.toggle('under-attack',button&&state.alarms.has(button.dataset.instanceId));});let button=document.querySelector('#attackAlarmDismiss');if(state.alarms.size&&!button){button=document.createElement('button');button.id='attackAlarmDismiss';button.className='alarm-dismiss';button.type='button';button.textContent='ОТБОЙ';button.onclick=dismissAttackAlarms;document.body.append(button)}if(button)button.hidden=!state.alarms.size}
const originalRefreshInventory=refreshInventory;
const originalRenderInventory=renderInventory;
renderInventory=function(data,windowElement){originalRenderInventory(data,windowElement);const container=windowElement.querySelector('.inventory-container');if(container){const title=(data.container?.title||'').toLowerCase();container.hidden=title.includes('craft')||title.includes('создан');if(!siteSettings.showCrafting)container.hidden=container.hidden||title.includes('craft')||title.includes('создан')}};
refreshInventory=async function(instanceId){const before=state.lastHealthByInstance.get(instanceId);await originalRefreshInventory(instanceId);const windowElement=document.querySelector(`.inventory-window[data-inventory-instance="${CSS.escape(instanceId)}"]`);const healthText=windowElement?.querySelector('.health-stat b')?.textContent||'';const health=Number.parseFloat(healthText);if(Number.isFinite(before)&&Number.isFinite(health)&&health<before-0.1)triggerAttackAlarm(instanceId);if(Number.isFinite(health))state.lastHealthByInstance.set(instanceId,health);applyAlarmVisuals()};
function applySlotLabelSettings(){const body=document.body;body.classList.toggle('hide-inventory-labels',!siteSettings.showSlotLabelsInventory);body.classList.toggle('hide-hotbar-labels',!siteSettings.showSlotLabelsHotbar);body.classList.toggle('hide-armor-labels',!siteSettings.showSlotLabelsArmor);body.classList.toggle('hide-container-labels',!siteSettings.showSlotLabelsContainers)}
applySlotLabelSettings();
function installSlotLabelSettings(){const host=$('#siteShortcuts')?.closest('.site-toggle-grid');if(!host)return;const options=[['siteSlotLabelsInventory','Подписи ячеек инвентаря','showSlotLabelsInventory'],['siteSlotLabelsHotbar','Подписи ячеек хотбара','showSlotLabelsHotbar'],['siteSlotLabelsArmor','Подписи ячеек брони','showSlotLabelsArmor'],['siteSlotLabelsContainers','Подписи ячеек сундуков и контейнеров','showSlotLabelsContainers']];for(const [id,text,key] of options){if($(`#${id}`))continue;const label=document.createElement('label');label.innerHTML=`<input id="${id}" type="checkbox"> ${text}`;host.append(label);const input=$(`#${id}`);input.checked=Boolean(siteSettings[key]);input.onchange=()=>{siteSettings[key]=input.checked;localStorage.setItem('baritoneSiteSettings',JSON.stringify(siteSettings));applySlotLabelSettings()}}}
installSlotLabelSettings();
